/* ============================================================
   UTILITIES
============================================================ */
const $ = (s, c = document) => c.querySelector(s);
const $$ = (s, c = document) => [...c.querySelectorAll(s)];
const clamp = (v, a, b) => Math.min(Math.max(v, a), b);
const reducedMotion = matchMedia("(prefers-reduced-motion: reduce)").matches;
const finePointer = matchMedia("(pointer: fine)").matches;
const refreshIcons = () => { if (window.lucide) lucide.createIcons(); };
const store = {
    get(k) { try { return localStorage.getItem(k); } catch (e) { return null; } },
    set(k, v) { try { localStorage.setItem(k, v); } catch (e) { } }
};

/* ============================================================
   THEME
============================================================ */
(function initTheme() {
    const saved = store.get("theme");
    if (saved) { document.documentElement.dataset.theme = saved; }
    else if (matchMedia("(prefers-color-scheme: light)").matches) { document.documentElement.dataset.theme = "light"; }
    $("#themeToggle").addEventListener("click", () => {
        const next = document.documentElement.dataset.theme === "dark" ? "light" : "dark";
        document.documentElement.dataset.theme = next;
        store.set("theme", next);
    });
})();

/* ============================================================
   REVEAL OBSERVER
============================================================ */
const revealIO = new IntersectionObserver(entries => {
    entries.forEach(e => { if (e.isIntersecting) { e.target.classList.add("in-view"); revealIO.unobserve(e.target); } });
}, { threshold: .12, rootMargin: "0px 0px -6% 0px" });
const observeReveals = (root = document) => $$("[data-reveal]", root).forEach(el => revealIO.observe(el));
observeReveals();

