/* ============================================================
   HERO — code editor typing
============================================================ */
(function typeEditor() {
    const LINES = [
        `<span class="c">// developer.profile</span>`,
        `<span class="k">const</span> asadUllah = {`,
        `  role: <span class="s">"Full Stack Web Developer"</span>,`,
        `  experience: <span class="s">"3+ years"</span>,`,
        `  projects: <span class="n">50</span>,`,
        `  stack: [<span class="s">"Laravel"</span>, <span class="s">"React"</span>, <span class="s">"Next.js"</span>],`,
        `  cms: <span class="s">"WordPress"</span>,`,
        `  databases: [<span class="s">"MySQL"</span>],`,
        `  <span class="f">available</span>: () => <span class="k">true</span>`,
        `};`,
    ];

    const body = $("#editorBody");

    if (reducedMotion) {
        body.innerHTML = LINES.map(l => `<div class="el">${l}</div>`).join("");
        return;
    }

    const strip = h => { const d = document.createElement("div"); d.innerHTML = h; return d.textContent; };
    let li = 0, ci = 0;
    let currentLine = null, textSpan = null, caret = null;

    function newLine() {
        currentLine = document.createElement("div");
        currentLine.className = "el";
        textSpan = document.createElement("span");
        caret = document.createElement("span");
        caret.className = "editor-caret";
        currentLine.append(textSpan, caret);
        body.appendChild(currentLine);
    }

    function step() {
        if (li >= LINES.length) return;

        const plain = strip(LINES[li]);

        if (ci === 0) newLine();

        if (ci < plain.length) {
            ci++;
            textSpan.textContent = plain.slice(0, ci);
            setTimeout(step, 14 + Math.random() * 30);
        } else {
            textSpan.remove();
            currentLine.innerHTML = LINES[li];
            currentLine.appendChild(caret);
            li++;
            ci = 0;
            setTimeout(step, li === 1 ? 260 : 90);
        }
    }

    setTimeout(step, 900);
})();

/* ============================================================
   HERO — interactive dot-grid canvas + mouse glow
============================================================ */
(function heroCanvas() {
    const canvas = $("#hero-canvas");
    const hero = $("#home");

    if (!canvas || !hero) return;

    const ctx = canvas.getContext("2d");
    const glow = $("#mouseGlow");
    const DPR = Math.min(devicePixelRatio || 1, 2);
    const GAP = 36, R = 170;

    let pts = [], W = 0, H = 0, running = false, raf = null;
    const mouse = { x: -9999, y: -9999 };

    function resize() {
        W = hero.offsetWidth;
        H = hero.offsetHeight;
        canvas.width = W * DPR;
        canvas.height = H * DPR;
        canvas.style.width = W + "px";
        canvas.style.height = H + "px";
        ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
        pts = [];

        for (let y = GAP / 2; y < H; y += GAP)
            for (let x = GAP / 2; x < W; x += GAP)
                pts.push({ ox: x, oy: y, x: 0, y: 0, e: 0 });
    }

    function frame() {
        ctx.clearRect(0, 0, W, H);
        const map = new Map();

        for (const p of pts) {
            const dx = p.ox - mouse.x, dy = p.oy - mouse.y;
            const d = Math.hypot(dx, dy);
            const f = d < R ? 1 - d / R : 0;
            const e = f * f;

            p.x = p.ox + (d > 1 ? dx / d * e * 12 : 0);
            p.y = p.oy + (d > 1 ? dy / d * e * 12 : 0);
            p.e = e;

            if (e > .02) map.set(Math.round(p.ox / GAP) + "_" + Math.round(p.oy / GAP), p);
        }

        // connecting lines between energized neighbors
        ctx.lineWidth = 1;

        for (const p of map.values()) {
            const keyX = (Math.round(p.ox / GAP) + 1) + "_" + Math.round(p.oy / GAP);
            const keyY = Math.round(p.ox / GAP) + "_" + (Math.round(p.oy / GAP) + 1);

            for (const key of [keyX, keyY]) {
                const q = map.get(key);

                if (q && Math.hypot(q.x - p.x, q.y - p.y) < GAP * 1.6) {
                    ctx.strokeStyle = `rgba(201,247,63,${Math.min(p.e, q.e) * .4})`;
                    ctx.beginPath();
                    ctx.moveTo(p.x, p.y);
                    ctx.lineTo(q.x, q.y);
                    ctx.stroke();
                }
            }
        }

        // energized dots
        for (const p of map.values()) {
            ctx.fillStyle = `rgba(201,247,63,${.15 + p.e * .75})`;
            ctx.beginPath();
            ctx.arc(p.x, p.y, 1 + p.e * 1.6, 0, 6.283);
            ctx.fill();
        }

        raf = running ? requestAnimationFrame(frame) : null;
    }

    function start() {
        if (running || reducedMotion || innerWidth < 640) return;
        running = true;
        raf = requestAnimationFrame(frame);
    }

    function stop() {
        running = false;

        if (raf) cancelAnimationFrame(raf);

        raf = null;
        ctx.clearRect(0, 0, W, H);
    }

    function sync() {
        const on = !reducedMotion && innerWidth >= 640;
        canvas.style.display = on ? "block" : "none";

        if (on) {
            resize();
            start();
        } else {
            stop();
        }
    }

    hero.addEventListener("pointermove", e => {
        const r = hero.getBoundingClientRect();
        mouse.x = e.clientX - r.left;
        mouse.y = e.clientY - r.top;

        if (glow) {
            glow.style.opacity = "1";
            glow.style.transform = `translate(${mouse.x}px, ${mouse.y}px) translate(-50%,-50%)`;
        }
    });

    hero.addEventListener("pointerleave", () => {
        mouse.x = -9999;
        mouse.y = -9999;

        if (glow) glow.style.opacity = "0";
    });

    new IntersectionObserver(([e]) => e.isIntersecting ? start() : stop(), { threshold: 0 }).observe(hero);

    let rt;

    addEventListener("resize", () => {
        clearTimeout(rt);
        rt = setTimeout(sync, 150);
    });

    sync();
})();

/* ============================================================
   TILT EFFECT (editor card, SaaS panel) + magnetic CTA
============================================================ */
if (finePointer && !reducedMotion) {
    $$("[data-tilt]").forEach(el => {
        el.addEventListener("pointermove", e => {
            const r = el.getBoundingClientRect();
            const rx = (0.5 - (e.clientY - r.top) / r.height) * 7;
            const ry = ((e.clientX - r.left) / r.width - 0.5) * 9;
            el.style.transform = `perspective(1000px) rotateX(${rx}deg) rotateY(${ry}deg)`;
        });

        el.addEventListener("pointerleave", () => {
            el.style.transform = "";
        });
    });

    const mag = $("#ctaWork");

    if (mag) {
        mag.addEventListener("pointermove", e => {
            const r = mag.getBoundingClientRect();
            const x = (e.clientX - r.left - r.width / 2) * .18;
            const y = (e.clientY - r.top - r.height / 2) * .3;
            mag.style.transform = `translate(${x}px, ${y}px)`;
        });

        mag.addEventListener("pointerleave", () => {
            mag.style.transform = "";
        });
    }
}

/* ============================================================
   SCROLL: progress bar, navbar state, timeline fill, to-top
============================================================ */
(function scrollSystem() {
    const bar = $(".scroll-progress"), nav = $("#navbar"), tl = $("#timeline"), fill = $("#tlFill"), toTop = $("#toTop");
    let ticking = false;

    function onScroll() {
        if (ticking) return;
        ticking = true;

        requestAnimationFrame(() => {
            const sc = scrollY;
            const max = document.documentElement.scrollHeight - innerHeight;

            bar.style.width = (max > 0 ? (sc / max) * 100 : 0) + "%";
            nav.classList.toggle("scrolled", sc > 30);
            toTop.classList.toggle("show", sc > 600);

            const r = tl.getBoundingClientRect();
            fill.style.height = clamp(innerHeight * .62 - r.top, 0, r.height) + "px";

            ticking = false;
        });
    }

    addEventListener("scroll", onScroll, { passive: true });
    onScroll();

    toTop.addEventListener("click", () => scrollTo({
        top: 0,
        behavior: reducedMotion ? "auto" : "smooth"
    }));
})();

/* active nav section */
(function activeNav() {
    const links = $$("[data-nav]");

    const io = new IntersectionObserver(entries => {
        entries.forEach(e => {
            if (e.isIntersecting) {
                links.forEach(l =>
                    l.classList.toggle("active", l.getAttribute("href") === "#" + e.target.id)
                );
            }
        });
    }, { rootMargin: "-40% 0px -55% 0px" });

    $$("main section[id]").forEach(s => io.observe(s));
})();

/* timeline items + chart activation */
(function timelineItems() {
    const io = new IntersectionObserver(entries => {
        entries.forEach(e => {
            if (e.isIntersecting) e.target.classList.add("in-view");
        });
    }, { threshold: .35 });

    $$(".tl-item").forEach(el => io.observe(el));

    const io2 = new IntersectionObserver(entries => {
        entries.forEach(e => {
            if (e.isIntersecting) {
                e.target.classList.add("in-view");
                io2.unobserve(e.target);
            }
        });
    }, { threshold: .3 });

    $$(".proj-card, .featured, .saas-panel").forEach(el => io2.observe(el));
})();

/* ============================================================
   COUNT-UP STATS
============================================================ */
(function counters() {
    const io = new IntersectionObserver(entries => {
        entries.forEach(e => {
            if (!e.isIntersecting) return;

            const el = e.target;
            const target = +el.dataset.count;
            const dur = 1200;
            const t0 = performance.now();

            if (reducedMotion) {
                el.textContent = target;
                io.unobserve(el);
                return;
            }

            (function tick(t) {
                const p = clamp((t - t0) / dur, 0, 1);
                el.textContent = Math.round(target * (1 - Math.pow(1 - p, 3)));

                if (p < 1) requestAnimationFrame(tick);
            })(t0);

            io.unobserve(el);
        });
    }, { threshold: .6 });

    $$("[data-count]").forEach(el => io.observe(el));
})();

/* ============================================================
   MOBILE MENU
============================================================ */
(function mobileMenu() {
    const burger = $("#hamburger"), menu = $("#mobileMenu");

    const setOpen = open => {
        document.body.classList.toggle("menu-open", open);
        document.body.style.overflow = open ? "hidden" : "";
        burger.setAttribute("aria-expanded", open);
        menu.setAttribute("aria-hidden", !open);

        $$(".mobile-menu .m-link").forEach((l, i) =>
            l.style.transitionDelay = open ? (i * 0.05 + 0.08) + "s" : "0s"
        );
    };

    burger.addEventListener("click", () =>
        setOpen(!document.body.classList.contains("menu-open"))
    );

    $$("#mobileMenu a").forEach(a =>
        a.addEventListener("click", () => setOpen(false))
    );

    addEventListener("keydown", e => {
        if (e.key === "Escape") setOpen(false);
    });
})();

/* ============================================================
   CUSTOM CURSOR (desktop only)
============================================================ */
(function cursor() {
    if (!finePointer || reducedMotion) return;

    document.body.classList.add("has-cursor");

    const dot = $(".cursor-dot"), ring = $(".cursor-ring");

    let x = -50, y = -50, rx = -50, ry = -50, shown = false;

    addEventListener("pointermove", e => {
        x = e.clientX;
        y = e.clientY;

        if (!shown) {
            shown = true;
            dot.style.opacity = "1";
            ring.style.opacity = "1";
        }

        dot.style.left = x + "px";
        dot.style.top = y + "px";
    }, { passive: true });

    (function loop() {
        rx += (x - rx) * .16;
        ry += (y - ry) * .16;

        ring.style.left = rx + "px";
        ring.style.top = ry + "px";

        requestAnimationFrame(loop);
    })();

    document.addEventListener("mouseover", e => {
        ring.classList.toggle(
            "on",
            !!e.target.closest("a, button, input, textarea, .proj-card, .skill-card, [data-tilt]")
        );
    });

    document.addEventListener("mouseleave", () => {
        dot.style.opacity = "0";
        ring.style.opacity = "0";
        shown = false;
    });
})();

/* ============================================================
   CONTACT FORM — validation + EmailJS submission
============================================================ */
(function contactForm() {
    const form = $("#contactForm"), btn = $("#submitBtn"), state = $("#formState");

    const rules = {
        name: v => v.trim().length >= 2 || "Please enter your name (min. 2 characters).",
        email: v => /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(v.trim()) || "Please enter a valid email address.",
        subject: v => v.trim().length >= 3 || "Subject needs at least 3 characters.",
        message: v => v.trim().length >= 10 || "Tell me a bit more — at least 10 characters.",
    };

    const setState = (type, html) => {
        state.className = "form-state show " + type;
        state.innerHTML = html;
        refreshIcons();
    };

    const validateField = name => {
        const input = form.elements[name];
        const wrap = form.querySelector(`[data-field="${name}"]`);
        const msg = wrap.querySelector(".field-msg");

        const res = rules[name](input.value);
        const ok = res === true;

        wrap.classList.toggle("err", !ok);
        input.setAttribute("aria-invalid", !ok);
        msg.textContent = ok ? "" : res;

        return ok;
    };

    Object.keys(rules).forEach(name => {
        form.elements[name].addEventListener("blur", () => validateField(name));

        form.elements[name].addEventListener("input", () => {
            if (form.querySelector(`[data-field="${name}"]`).classList.contains("err")) {
                validateField(name);
            }
        });
    });

    form.addEventListener("submit", async e => {
        e.preventDefault();

        if (form.elements.company.value) return; // honeypot: silently drop bots

        const ok = Object.keys(rules).map(validateField).every(Boolean);

        if (!ok) {
            setState(
                "info",
                `<i data-lucide="alert-triangle"></i><span><strong>Almost there</strong> — please fix the highlighted fields and try again.</span>`
            );

            const firstErr = form.querySelector(".field.err input, .field.err textarea");

            if (firstErr) firstErr.focus();

            return;
        }

        btn.classList.add("loading");
        btn.disabled = true;

        try {
            await emailjs.sendForm(
                CONFIG.EMAILJS_SERVICE_ID,
                CONFIG.EMAILJS_TEMPLATE_ID,
                form
            );

            btn.classList.remove("loading");
            btn.disabled = false;

            setState(
                "ok",
                `<i data-lucide="check-circle-2"></i><span><strong>Message sent.</strong> Thanks — I'll get back to you soon.</span>`
            );

            form.reset();

        } catch (err) {
            btn.classList.remove("loading");
            btn.disabled = false;

            setState(
                "info",
                `<i data-lucide="alert-triangle"></i><span><strong>Something went wrong.</strong> Please try again or email me directly at <a href="mailto:johnbhai608@gmail.com" style="color:var(--accent-text)">johnbhai608@gmail.com</a>.</span>`
            );
        }
    });
})();

refreshIcons();
window.addEventListener("load", refreshIcons);



